INSERT INTO public.bpei_assessment_questions(level,ordinal,domain,question,evaluator_answer) VALUES
(2,1,'Windows','À quoi sert l''Observateur d''événements ?','Relier événements datés et erreurs système ou application.'),
(2,2,'Windows','Quel usage de la commande sfc /scannow ?','Examiner et réparer certains fichiers Windows protégés selon le contexte.'),
(2,3,'Windows','Comment diagnostiquer un démarrage lent ?','Mesurer les applications de démarrage, services, disque et ressources.'),
(2,4,'Windows','Pourquoi comparer la panne sur un second profil ?','Isoler les paramètres propres à un utilisateur des défauts globaux.'),
(2,5,'Pilotes','Comment interpréter un code d''erreur de périphérique ?','Vérifier la signification du code, pilote et matériel avant toute action.'),
(2,6,'Matériel','Quelles sont les limites d''un rapport SMART ?','Il indique certains défauts disques mais ne garantit pas leur prédiction.'),
(2,7,'Matériel','Pourquoi exécuter un test mémoire ?','Rechercher des erreurs pouvant provoquer plantages ou corruption.'),
(2,8,'Stockage','Que faire face à un disque qui claque ?','Limiter les accès et proposer une récupération spécialisée pour les fichiers importants.'),
(2,9,'Stockage','Que signifie la règle de sauvegarde 3-2-1 ?','Trois copies, deux types de support et une copie hors site.'),
(2,10,'Stockage','Comment prouver qu''une sauvegarde est utilisable ?','Effectuer une restauration contrôlée et vérifier les fichiers récupérés.'),
(2,11,'Réseau','Comment distinguer un problème DNS d''un défaut IP ?','Comparer résolution de noms et connectivité directe vers une adresse valide.'),
(2,12,'Réseau','Pourquoi une passerelle incorrecte empêche Internet ?','Les paquets destinés aux autres réseaux ne suivent plus le bon routeur.'),
(2,13,'Réseau','À quoi sert le masque de sous-réseau ?','Définir les adresses considérées comme appartenant au même réseau.'),
(2,14,'Réseau','Différence pratique entre switch et routeur ?','Un switch relie un réseau local ; un routeur interconnecte plusieurs réseaux.'),
(2,15,'Wi-Fi','Comment diagnostiquer des coupures Wi-Fi ?','Comparer couverture, canaux, interférences, bande et liaison filaire.'),
(2,16,'Sécurité','Quel est le principe du moindre privilège ?','N''accorder que les permissions indispensables à chaque tâche.'),
(2,17,'Sécurité','Différence entre chiffrement et hachage ?','Le chiffrement utilise une clé pour revenir au clair ; le hachage fournit une empreinte.'),
(2,18,'Sécurité','Comment procéder devant une suspicion de malware ?','Isoler si nécessaire, préserver les preuves et utiliser des outils fiables.'),
(2,19,'Support','Que demander avant une prise en main à distance ?','Consentement explicite, périmètre autorisé et conditions de fin de session.'),
(2,20,'Comptes','Que prévoir lors d''une migration d''ordinateur ?','Transférer les données autorisées, profils, licences et accès avec contrôles.'),
(2,21,'Courriel','Comment diagnostiquer une boîte mail qui ne reçoit rien ?','Comparer webmail, quota, DNS et configuration du compte.'),
(2,22,'Qualité','À quoi servent les tests de non-régression ?','Vérifier que la réparation n''a pas créé de nouveaux dysfonctionnements.'),
(2,23,'Commercial','Que faire si la panne dépasse le devis initial ?','Expliquer et obtenir un accord complémentaire avant de poursuivre.'),
(2,24,'RGPD','Comment minimiser un ticket de support ?','Conserver uniquement les éléments nécessaires et pas de secrets.'),
(2,25,'Escalade','Quand transférer une intervention à un spécialiste ?','Lorsqu''une panne dépasse sa compétence, ses outils ou son périmètre d''assurance.');